cssEstilo:
.prem-a4-container { max-width: 896px; margin: 2.5rem auto; padding: 2rem; background-color: #ffffff; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1); border: 1px solid #e5e7eb; font-family: sans-serif; }
.prem-a4-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #2563eb; padding-bottom: 1rem; }
.prem-a4-header-left { flex: 1; }
.prem-a4-title { font-size: 1.875rem; font-weight: 700; color: #1d4ed8; text-transform: uppercase; line-height: 1; margin: 0; }
.prem-a4-ruc { font-size: 0.875rem; color: #4b5563; margin-top: 0.5rem; margin-bottom: 0; }
.prem-a4-address { font-size: 0.875rem; color: #4b5563; margin: 0; }
.prem-a4-motto { font-size: 0.875rem; color: #4b5563; font-style: italic; margin: 0; }
.prem-a4-header-right { text-align: right; }
.prem-a4-doc-box { background-color: #eff6ff; padding: 1rem; border: 1px solid #bfdbfe; border-radius: 0.5rem; }
.prem-a4-doc-type { color: #1d4ed8; font-weight: 700; text-transform: uppercase; margin: 0; }
.prem-a4-doc-number { font-size: 1.25rem; font-family: monospace; margin: 0; }
.prem-a4-date { font-size: 0.75rem; color: #6b7280; margin-top: 0.5rem; font-style: italic; margin-bottom: 0; }
.prem-a4-data-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; margin: 1.5rem 0; font-size: 0.875rem; }
.prem-a4-data-col { display: flex; flex-direction: column; gap: 0.25rem; }
.prem-a4-data-col.right { text-align: right; }
.prem-a4-data-row { margin: 0; }
.prem-a4-label { font-weight: 700; text-transform: uppercase; color: #374151; }
.prem-a4-table { width: 100%; text-align: left; font-size: 0.875rem; margin-bottom: 2rem; border-collapse: collapse; }
.prem-a4-table thead tr { background-color: #2563eb; color: #ffffff; text-transform: uppercase; }
.prem-a4-table th { padding: 0.5rem 1rem; border: 1px solid #1d4ed8; }
.prem-a4-tbody { color: #4b5563; }
.prem-a4-footer-row { display: flex; justify-content: space-between; }
.prem-a4-indications-box { width: 50%; padding: 1rem; background-color: #f9fafb; border-radius: 0.5rem; border: 1px dashed #d1d5db; }
.prem-a4-indications-label { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; color: #6b7280; margin-bottom: 0.25rem; text-decoration: underline; }
.prem-a4-indications-text { font-size: 0.75rem; font-style: italic; color: #4b5563; margin: 0; }
.prem-a4-totals-box { width: 33.333333%; display: flex; flex-direction: column; gap: 0.5rem; text-align: right; }
.prem-a4-total-row { display: flex; justify-content: space-between; padding: 0 0.5rem; font-size: 0.875rem; }
.prem-a4-grand-total { display: flex; justify-content: space-between; padding: 0 0.5rem; font-size: 1.25rem; font-weight: 700; border-top: 1px solid currentColor; padding-top: 0.5rem; color: #1e40af; }
.prem-a4-bottom { margin-top: 3rem; text-align: center; font-size: 0.75rem; color: #9ca3af; border-top: 1px solid currentColor; padding-top: 1rem; }
.prem-a4-bottom-text { margin: 0; }

.prem-ticket-container { width: 80mm; margin: 0 auto; padding: 1rem; background-color: #ffffff; border: 1px solid #e5e7eb; font-family: monospace; font-size: 0.75rem; }
.prem-ticket-header { text-align: center; margin-bottom: 1rem; }
.prem-ticket-title { font-size: 1rem; font-weight: 900; text-transform: uppercase; margin: 0; }
.prem-ticket-info { margin: 0; }
.prem-ticket-info-box { border-top: 1px dashed #000000; border-bottom: 1px dashed #000000; padding: 0.5rem 0; margin: 0.5rem 0; }
.prem-ticket-table { width: 100%; margin: 0.5rem 0; border-collapse: collapse; }
.prem-ticket-table thead tr { border-bottom: 1px solid #000000; }
.prem-ticket-table th { padding: 0.25rem 0; }
.prem-ticket-totals { border-top: 1px solid #000000; padding-top: 0.5rem; margin-top: 1rem; display: flex; flex-direction: column; gap: 0.25rem; }
.prem-ticket-total-row { display: flex; justify-content: space-between; }
.prem-ticket-grand-total { display: flex; justify-content: space-between; font-weight: 700; font-size: 0.875rem; border-top: 1px dashed #000000; padding-top: 0.25rem; }
.prem-ticket-footer { margin-top: 1.5rem; text-align: center; }
.prem-ticket-footer-text { margin: 0; }
.prem-ticket-qr-placeholder { display: flex; justify-content: center; margin-top: 0.5rem; }
.prem-ticket-qr-box { width: 6rem; height: 1rem; background-color: #d1d5db; }
